SELECT a.id,a.song_count,a.duration,a.size,(SELECT COUNT(*) FROM song_masters sm WHERE sm.album_id=a.id) actual_count,(SELECT COALESCE(SUM(sm.duration),0) FROM song_masters sm WHERE sm.album_id=a.id) actual_duration,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id=a.id) actual_size FROM albums a WHERE a.id IN ('pending-uploads','al-9c7ec22ef5');
